rotateWebhookEndpointSecret.go:
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"

	trevol "github.com/trevol/trevol-go"
	"github.com/trevol/trevol-go/generado"
)

func main() {
	ctx := context.Background()
	c, err := trevol.NewClient(os.Getenv("TREVOL_API_KEY"))
	if err != nil {
		log.Fatal(err)
	}

	var entrada generado.WebhookEndpointRotateInput
	cuerpo := `{
  "grace_period_hours": 24
}`
	if err := json.Unmarshal([]byte(cuerpo), &entrada); err != nil {
		log.Fatal(err)
	}

	resultado, _, err := c.WebhookEndpointsAPI.RotateWebhookEndpointSecret(ctx, "we_3f0c1a2b3f0c1a2b3f0c1a2b3f0c1a2b").
		WebhookEndpointRotateInput(entrada).
		Execute()
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(resultado)
}

